/module-kit ^0.6.0,\n  @nekazari/module-builder ^2.0.0.","tree":{"sha":"ada5cc32932957f3ffebdb69ee2b642ab6a917d4","url":"https://api.github.com/repos/nkz-os/catastro-sp-module-nekazari/git/trees/ada5cc32932957f3ffebdb69ee2b642ab6a917d4"},"url":"https://api.github.com/repos/nkz-os/catastro-sp-module-nekazari/git/commits/d25934a6e28d1b12725706128e63d92114f140c1","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/125390342?v=4","events_url":"https://api.github.com/users/k8-benetis/events{/privacy}","followers_url":"https://api.github.com/users/k8-benetis/followers","following_url":"https://api.github.com/users/k8-benetis/following{/other_user}","gists_url":"https://api.github.com/users/k8-benetis/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/k8-benetis","id":125390342,"login":"k8-benetis","node_id":"U_kgDOB3lOBg","organizations_url":"https://api.github.com/users/k8-benetis/orgs","received_events_url":"https://api.github.com/users/k8-benetis/received_events","repos_url":"https://api.github.com/users/k8-benetis/repos","site_admin":false,"starred_url":"https://api.github.com/users/k8-benetis/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/k8-benetis/subscriptions","type":"User","url":"https://api.github.com/users/k8-benetis","user_view_type":"public"},"html_url":"https://github.com/nkz-os/catastro-sp-module-nekazari/commit/d25934a6e28d1b12725706128e63d92114f140c1","node_id":"C_kwDOQ3exUNoAKGQyNTkzNGE2ZTI4ZDFiMTI3MjU3MDYxMjhlNjNkOTIxMTRmMTQwYzE","parents":[{"html_url":"https://github.com/nkz-os/catastro-sp-module-nekazari/commit/b1af516a8a2b74134f9e607d1d6cea4b0fe69b40","sha":"b1af516a8a2b74134f9e607d1d6cea4b0fe69b40","url":"https://api.github.com/repos/nkz-os/catastro-sp-module-nekazari/commits/b1af516a8a2b74134f9e607d1d6cea4b0fe69b40"}],"sha":"d25934a6e28d1b12725706128e63d92114f140c1","url":"https://api.git